//! Tool argument validation for schemas built with TypeBox: TS `validateToolArguments` runs TypeBox
//! 1.3.27 `Value.Convert` (arrays wrap scalars, "TRUE"/"1" are booleans, "" is 0, integers
//! truncate, null is "null" for strings, ...) before the JSON Schema coercion. Fixture generated by
//! `scripts/golden/gen-validation.mjs` from the TypeScript sources.

use pi_ai::types::{Tool, ToolCall};
use pi_ai::utils::js_json::js_json_stringify;
use pi_ai::validate_tool_arguments;
use serde::Deserialize;
use serde_json::{Map, Value};

#[derive(Deserialize)]
struct Case {
    name: String,
    parameters: Value,
    arguments: Map<String, Value>,
    ok: Option<Value>,
    error: Option<String>,
}

#[test]
fn typebox_schemas_convert_arguments_like_value_convert() {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/tests/fixtures/typebox_validation.json");
    let cases: Vec<Case> = serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap();
    let mut failures = Vec::new();
    for case in &cases {
        let tool = Tool::new(&case.name, &case.name, case.parameters.clone()).with_typebox(true);
        let call = ToolCall {
            id: "call".into(),
            name: case.name.clone(),
            arguments: case.arguments.clone(),
            thought_signature: None,
            namespace: None,
            arguments_error: None,
        };
        let actual = validate_tool_arguments(&tool, &call);
        let matches = match (&actual, &case.ok, &case.error) {
            (Ok(value), Some(expected), None) => js_json_stringify(value) == js_json_stringify(expected),
            (Err(error), None, Some(expected)) => error.0 == *expected,
            _ => false,
        };
        if !matches {
            failures.push(format!(
                "{} {}\n  expected {:?} {:?}\n  got      {:?}",
                case.name,
                Value::Object(case.arguments.clone()),
                case.ok.as_ref().map(js_json_stringify),
                case.error,
                actual.as_ref().map(js_json_stringify).map_err(|e| e.0.clone())
            ));
        }
    }
    assert!(failures.is_empty(), "{} of {} cases differ:\n{}", failures.len(), cases.len(), failures.join("\n"));
}
